"""Build download"""
import re
import os
import json
import subprocess
from builtins import object
from collections import OrderedDict
from past.builtins import basestring
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.build_download.exceptions import *
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.recovery.recovery import Recovery
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file

logger = BackgroundLogger.Instance()


class BuildDownload(object):
    """Build download"""
    def find_latest_build(self, wft_profile):
        """
            Performs following operation:
            1. Gets the contents of the wft page content in json format and apply relevant filters and matches with the
            build entry. If the build matches it reruns the latest build or it throws BuildNotFound exception.
            Args:
                 wft_filters_file: contains filters for choosing the latest build from WFT web page. This file will be
                 in fw_user_path/testcase/ resources directory

            Returns: build, which we get from the build_entry dict, if not found exception is thrown.

        """
        config_base_path = get_config_variable(['config_base_path'])
        wft_filters_file = get_resource_file('wft_filters.json', config_base_path)
        wft_filters, wft_filters_file, download_url, buildnum_regex, package_template = \
            self._get_wft_related_dependencies(wft_filters_file, wft_profile)
        state_criteria = self._get_state_criteria(wft_filters)
        latest_build_num = self._get_latest_buildnum_in_wft_response(buildnum_regex, state_criteria, wft_filters_file)
        logger.info('latest_buildnum: {}, download_url: {}, package_template {}'.format(latest_build_num, download_url,
                                                                                        package_template))
        return download_url, latest_build_num, package_template

        # return latest_build_num, download_url, package_template

    def _get_latest_buildnum_in_wft_response(self, buildnum_regex, state_criteria, wft_filters_file):
        response_file = self._get_wft_page_content(wft_filters_file)
        with open(response_file, 'r') as fh:
            response_content = fh.read()
        json_content = json.loads(response_content)
        if len(json_content) > 0 and 'items' in list(json_content.keys()):
            for build_entry in json_content['items']:
                if self._check_if_build_matches_state_criteria(build_entry,
                                                               state_criteria):
                    build_baseline_val = build_entry['baseline']
                    buildnum_matches = re.findall(buildnum_regex,
                                                  build_baseline_val)
                    if len(buildnum_matches) == 0:
                        raise Exception('No match for buildnum_regex'
                                        ' {} in {}'.format(buildnum_regex,
                                                           build_baseline_val))
                    return buildnum_matches[0]
                    # return build_entry["baseline"], download_url, package_prefix, package_suffix
        raise BuildNotFound('No build matched the given criteria in wft_filters.json')

    # def download_latest_build(self, latest_build, download_url, package_prefix, package_suffix):
    def download_latest_build(self, latest_buildnum, download_url, package_template, download_path, remote_session=None):
        """
        Performs following operation:
        1. Executes wget command to download the latest build from the download url given, in the execution logs dir.
        Args:
            latest_build: latest build name which is to be downloaded.
            download_url: URL from where the build needs to be downloaded
            package_suffix: extension of the build package
            download_path: path to download the build
        Returns: destination file
        """
        Recovery().disk_space_issue_recovery()
        # package_name = '{}{}{}'.format(package_prefix, latest_build, package_suffix)
        download_url = download_url.format(latest_build_num=latest_buildnum)
        package_name = package_template.format(latest_build_num=latest_buildnum)
        dest = os.path.join(download_path, package_name)
        if remote_session is None:
            if not os.path.exists(os.path.dirname(dest)):
                os.makedirs(os.path.dirname(dest))
            wget_cmd = 'wget -O {} {}{}'.format(dest, download_url, package_name)
            logger.debug(wget_cmd)
            subprocess.check_output(wget_cmd, shell=True)
            return dest, package_name
        else:
            dest = '/d/oss/global/swmanager/swm_temp/{}'.format(package_name)
            wget_cmd = 'wget -O {} {}{}'.format(dest, download_url, package_name)
            wget_cmd = 'export https_proxy=http://10.158.100.6:8080/; {}'.format(wget_cmd)
            logger.debug(wget_cmd)
            remote_session.execute_command(wget_cmd)
            build_cmd = "unzip -l /d/oss/global/swmanager/swm_temp/{} | grep TargetBD".format(package_name)
            build_str = remote_session.execute_command(build_cmd)
            logger.debug('build_str: {}'.format(build_str))
            build_version = re.findall('SBTS.*ENB[_0-9+]+', build_str[0])
#            build_version = re.findall('SBTS.*ENB.+', build_str[0])
            logger.debug('build_ver: {}'.format(build_version))
            # remote_session.run_command(wget_cmd)
            # remote_host_session.exec_command('chmod')
            return dest, package_name, build_version[0]

    def _get_wft_page_content(self, filters_file):
        """
        performs following operation:
        1. Executes "CURL" command to get the response from the wft in json format which will be stored in response.json
         based on the filters given in filters_file.
        Args:
            filters_file:

        Returns: response.json file

        """
        response_file = 'response.json'
        curl_cmd = "curl -H 'Accept: application/json' -H 'Content-Type:application/json' -d@{} " \
                   "https://wft.int.net.nokia.com:8091/api/v1/build.json -o {}".format(filters_file, response_file)
        subprocess.check_output(curl_cmd, shell=True)
        return response_file

    def _check_if_build_matches_state_criteria(self, build_entry, state_criteria):
        """

        Args:
            build_entry: build entry dict which we get from response.json
            state_criteria: this is got from the wft filter file from testcase directory

        Returns:

        """
        # Keep this function until WFT is corrected to display only records that match the filters
        if build_entry['state'].lower() in state_criteria:
            return True
        return False

    def _get_wft_related_dependencies(self, wft_filters_file, wft_profile):
        """

        Args:
            wft_filters_file: Resource file, contains filters for choosing the latest build from WFT web page. This file
             will be in fw_user_path/testcase/ resources directory
            wft_profile: User given profile

        Returns: wft_filters_built_json, wft_filters_file, download_url, package_name_suffix
        """
        wft_filters_built_json = OrderedDict()
        with open(wft_filters_file, 'r') as fh:
            wft_filters_data = fh.read()
        wft_filters_json = json.loads(wft_filters_data)
        wft_filters_built_json.update(wft_filters_json['fixed_parameters'])
        filter_file_suffix, view_filter_attrs, download_url, buildnum_regex, package_template =\
            self._get_wft_profile_params(wft_filters_json, wft_profile)
        wft_filters_built_json["view_filters_attributes"] = view_filter_attrs
        wft_filters_file = os.path.join('execution_logs', 'wft_filters_{}.json'.format(filter_file_suffix))
        with open(wft_filters_file, 'w') as fh:
            json.dump(wft_filters_built_json, fh)
        return wft_filters_built_json, wft_filters_file, download_url, buildnum_regex, package_template

    def _get_wft_profile_params(self, wft_filters_json, wft_profile):
        wft_profile_dict = {}
        # wft_filters_built_json.update(wft_filters_json['profiles'][wft_profile])
        if isinstance(wft_profile, basestring):
            try:
                wft_profile_dict = wft_filters_json['profiles'][wft_profile]
                filter_file_suffix = wft_profile
            except KeyError as err:
                raise Exception('Exception :: {} \n Given profile {} does not exist'.format(err, wft_profile))
        elif isinstance(wft_profile, dict):
            wft_profile_dict = wft_profile
            filter_file_suffix = ''
        else:
            raise Exception('Given wft_profile unsupported')
        view_filter_attrs = wft_profile_dict.get("view_filters_attributes")
        download_url = wft_profile_dict['download_url']
        buildnum_regex = wft_profile_dict.get("buildnum_regex", '')
        package_template = wft_profile_dict.get("package_template", '')
        return filter_file_suffix, view_filter_attrs, download_url, buildnum_regex, package_template
        # return filter_file_suffix, wft_profile_dict

    def _get_state_criteria(self, wft_filters):
        """
        Gets the state criteria from the wft filters file
        Args:
            wft_filters: contains filters for choosing the latest build from WFT web page. This file will be in
             fw_user_path/testcase/ resources directory

        Returns: state criteria

        """
        state_criteria = []
        for wft_filter in list(wft_filters['view_filters_attributes'].values()):
            if wft_filter['column'].lower() == 'state':
                for state in wft_filter['value']:
                    state_criteria.append(state.lower())
        return state_criteria
